import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-023 — Star, outer-scale and black-hole panels follow the planet pattern","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-023-star-and-outer-panels-follow-the-planet-pattern.md","filePath":"uxs/decisions/UXD-023-star-and-outer-panels-follow-the-planet-pattern.md"}'),s={name:"uxs/decisions/UXD-023-star-and-outer-panels-follow-the-planet-pattern.md"};function r(l,e,i,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="uxd-023-—-star-outer-scale-and-black-hole-panels-follow-the-planet-pattern" tabindex="-1">UXD-023 — Star, outer-scale and black-hole panels follow the planet pattern <a class="header-anchor" href="#uxd-023-—-star-outer-scale-and-black-hole-panels-follow-the-planet-pattern" aria-label="Permalink to &quot;UXD-023 — Star, outer-scale and black-hole panels follow the planet pattern&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-12 (proposed in the B3 brief and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-12 — &quot;all open questions of §10 (Q1–Q8) approved as recommended&quot; (<code>docs/wip/2026-11-12-slice-B3-brief.md</code>, line 26). SN2, MW3 and MW5 are the operator&#39;s points (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code> lines 206, 214, 215); UXD-008 recorded the star half. The layout and the shared component are the lead&#39;s resolution.</li><li><strong>Answers</strong>: SN2, MW3, MW5; slice B3; Q1 to Q8 of the brief</li><li><strong>Changes</strong>: <code>UniversePanelBody.svelte</code> and <code>UniverseFacts.svelte</code> (new), the nine panels on them (<code>StarPanel</code>, <code>MilkyWayPanel</code>, <code>LocalGroupPanel</code>, <code>LocalSheetPanel</code>, <code>VirgoPanel</code>, <code>LaniakeaPanel</code>, <code>CosmicWebPanel</code>, <code>BlackHolePanel</code>, <code>DeepSkyPanel</code>), <code>PanelHeroImage</code> (optional <code>position</code>), <code>explore-scene-host.ts</code> (a hole opens its panel in place), <code>image-hero.ts</code> (surfaces <code>stars</code>, <code>black-holes</code>), <code>static/data/universe/panel-heroes.json</code> and <code>star-gallery.json</code>; Design System §5.3; <a href="./../UXS-001">UXS-001</a> detail panel tabs; <a href="./../UXS-014">UXS-014</a>; <a href="./../IA">IA</a>; <code>AGENTS.md</code>; <code>docs/adr/TA.md</code>; messages (5 keys added, 2 removed). Extends <a href="./UXD-008-star-panel-one-hero-and-in-the-sky-tab">UXD-008</a>, which is not rewritten.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>StarPanel</code> stacked up to three blocks (photo, portrait, finder) above its tabs and pushed Overview below the fold (SN2). Eight outer panels (Milky Way to Cosmic web, black holes, deep-sky) were one private block copied eight times, in <code>rem</code> sizes outside the type scale, with no hero and no tabs (MW3). Selecting the Sagittarius A* pin replaced the main area with the lensing render and opened a text-only panel. No outer panel showed a photograph; the deep-sky photo was only the immersive main area (MW5). Evidence: the brief&#39;s §2.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ul><li><strong>Shared body</strong> (chosen) or eight edits: one component is the only way the panels stay alike.</li><li><strong>Hero box</strong>: the planet&#39;s 16:9 cover (chosen, with a reviewed focal point per image) or a natural-ratio box capped at 280 px (no consistency, no crop).</li><li><strong>Part-of photos</strong> (Tarantula for the LMC): hero of the parent with the pictured part named (chosen) or exact matches only (three panels).</li><li><strong>Black holes</strong>: open in place with the lensing behind an action (chosen, all four holes) or Sagittarius A* only.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>One body</strong> (<code>UniversePanelBody</code>): the one-row header, the action row (at most three chips), ONE hero, the tab row, then Overview as lead text (<code>.editorial</code>), facts (the planet&#39;s cell look, three per row), extras, science, the read-more link. No colour and no size of its own: tokens only.</li><li><strong>One hero, no empty slot.</strong> An image hero is <code>PanelHeroImage</code> (16:9 cover, opens the lightbox) and the caption names the author and, for a photo of a part of the entity, what is pictured (&quot;Pictured: Tarantula Nebula&quot;). With no image the star&#39;s drawn portrait is the hero; with neither there is no hero block.</li><li><strong>Tabs</strong>: OVERVIEW; GALLERY second and only with two or more images (the grid is all but the hero); the panel&#39;s own tabs after. One tab draws no tab row. <strong>A star&#39;s tabs</strong> are OVERVIEW · GALLERY · IN THE SKY · SYSTEM · TECHNICAL. IN THE SKY holds the constellation finder, the constellation named, a zodiac note for the thirteen constellations the ecliptic crosses, and the action &quot;Show constellation lines&quot; (turns the science lens and the Constellations layer on). Constellation names stay English (<code>iau-constellations.ts</code>).</li><li><strong>Heroes for the outer levels</strong> come from <code>panel-heroes.json</code>: 10 entries (omega Centauri, the Sun, the LMC and SMC at two levels each, Andromeda, two Local Sheet groups, Perseus–Pisces) and two black holes. A deep-sky photo is served as its 700 px thumb (the originals are not on the WebP ladder). Laniakea and Virgo have none.</li><li><strong>Black holes open in place.</strong> Selecting a hole at its scale (pin, INDEX row, <code>?galaxy=</code>) opens its panel and leaves the main area; the action &quot;See the lensing simulation&quot; enters the takeover. <code>?bh=&lt;id&gt;</code> still enters the takeover directly, also on a mounted page. A hole&#39;s panel open in place is a selection at its scale like any member&#39;s (review 2026-11-13): any other pick closes it, the scale&#39;s Reset is live while it is open and after its ×, and a Milky Way hole is mirrored as <code>?galaxy=&lt;id&gt;</code> (shareable, reloads to the same panel). Sagittarius A* has the EHT 2022 image (ESO <code>eso2208-eht-mwa</code>, credit &quot;EHT Collaboration&quot;, CC BY 4.0, read on <code>eso.org/public/outreach/copyright/</code>), M87* the EHT 2019 image already in the repo.</li><li><strong>Gallery for stars</strong>: a sidecar <code>star-gallery.json</code> and loader ship empty; no star has a second image, so no Gallery tab shows at ship (L29 lists the content).</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The star panel&#39;s tab ids stay <code>star-tab-&lt;id&gt;</code> / <code>star-tabpanel</code>. <code>.enter-system</code> is gone (a chip, test id <code>enter-system</code>); its <code>chip.spec.ts</code> allow-list entry goes. The star hero is a 16:9 crop now: Sirius and Vega carry a reviewed focal point (<code>stars-hero-overrides.json</code>). Not changed: the planet family and its heroes, the lensing scene, the entity pages, the INDEX. L30 (finder for deep-sky objects) stays deferred.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>scripts/check-universe-panels.sh</code> prints <code>B3-CHECK violations: 0</code>; <code>UniversePanelBody.test.ts</code>, <code>universe-heroes.test.ts</code>, <code>tests/e2e/universe-panels.spec.ts</code>, <code>tests/e2e/type-floor.spec.ts</code> (Milky Way, black hole and deep-sky panels added); validate-data checks every hero key against its file and provenance row.</p>',12)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
